<?php

namespace Prado\Test\Unit\Util\Email;

use Prado\Util\Email\TEmailModule;
use Prado\TPropertyValue;

/**
 * Test class for TEmailModule.
 * Generated by PHPUnit on 2026-03-30 at 12:00:00.
 */
class TEmailModuleTest extends \PHPUnit\Framework\TestCase
{
	/**
	 * @var TEmailModule
	 */
	protected $object;

	/**
	 * Sets up the fixture, for example, opens a network connection.
	 * This method is called before a test is executed.
	 */
	protected function setUp(): void
	{
		$this->object = new TEmailModule();
	}

	/**
	 * Tears down the fixture, for example, closes a network connection.
	 * This method is called after a test is executed.
	 */
	protected function tearDown(): void
	{
	}

	/**
	 * @covers Prado\Util\Email\TEmailModule::__construct
	 */
	public function testConstruct()
	{
		$this->assertInstanceOf(TEmailModule::class, $this->object);
	}

	/**
	 * @covers Prado\Util\Email\TEmailModule::getBasePageClass
	 * @covers Prado\Util\Email\TEmailModule::setBasePageClass
	 */
	public function testBasePageClass()
	{
		// Test default value
		$this->assertEquals('\Prado\Util\Email\UI\TEmailPage', $this->object->getBasePageClass());
		
		// Test setting new value
		$this->object->setBasePageClass('TestPageClass');
		$this->assertEquals('TestPageClass', $this->object->getBasePageClass());
	}

	/**
	 * @covers Prado\Util\Email\TEmailModule::getDefaultCcAddress
	 * @covers Prado\Util\Email\TEmailModule::setDefaultCcAddress
	 */
	public function testDefaultCcAddress()
	{
		$this->assertNull($this->object->getDefaultCcAddress());
		
		$this->object->setDefaultCcAddress('cc@example.com');
		$this->assertEquals('cc@example.com', $this->object->getDefaultCcAddress());
	}

	/**
	 * @covers Prado\Util\Email\TEmailModule::getDefaultBccAddress
	 * @covers Prado\Util\Email\TEmailModule::setDefaultBccAddress
	 */
	public function testDefaultBccAddress()
	{
		$this->assertNull($this->object->getDefaultBccAddress());
		
		$this->object->setDefaultBccAddress('bcc@example.com');
		$this->assertEquals('bcc@example.com', $this->object->getDefaultBccAddress());
	}

	/**
	 * @covers Prado\Util\Email\TEmailModule::getMailAdditionalParameters
	 * @covers Prado\Util\Email\TEmailModule::setMailAdditionalParameters
	 */
	public function testMailAdditionalParameters()
	{
		$this->assertEquals('', $this->object->getMailAdditionalParameters());
		
		$this->object->setMailAdditionalParameters('-f sender@example.com');
		$this->assertEquals('-f sender@example.com', $this->object->getMailAdditionalParameters());
	}
}